skeleton:
sealed interface Forme permits Cercle, Carre { }
record Cercle(double rayon) implements Forme { }
record Carre(double cote) implements Forme { }

static double aire(Forme f) {
    // Complete le switch sans default : les deux cas couvrent tout l'ensemble scelle
    return switch (f) {
        // ...
    };
}

solution:
static double aire(Forme f) {
    return switch (f) {
        case Cercle c -> Math.PI * c.rayon() * c.rayon();
        case Carre ca -> ca.cote() * ca.cote();
    };
}
